import {buildForceDiagram,FORCE_GROUPS} from './force-data.js';
import {getLanguage} from './i18n.js';
export function createForceControls(root,button,getState,getMetrics){root.setAttribute('data-i18n-skip','');let language,lastMetric,lastConfig;const lang=(it,en)=>getLanguage()==='en'?en:it;function render(){const expanded=root.querySelector('.force-extra')?.open;language=getLanguage();root.innerHTML=`<p class="force-hint">${lang('Passa sui punti per leggere i centri; su touch, tocca per aprire o chiudere il dettaglio. Aggiungi solo i vettori che ti interessano.','Hover over a point to read a centre; on touch, tap to open or close its detail. Add only the vector layers you need.')}</p><fieldset class="force-groups"><legend>${lang('Vettori da mostrare','Vector layers')}</legend>${FORCE_GROUPS.map(([id,it,en])=>`<label><input type="checkbox" data-force-group="${id}"><span>${getLanguage()==='en'?en:it}</span></label>`).join('')}</fieldset><details class="force-extra"${expanded?' open':''}><summary>${lang('Scala e valori numerici','Scale and numerical values')}</summary><label class="force-scale">${lang('Dimensione frecce','Arrow size')}<input id="forceScale" type="range" min=".5" max="2" value="1" step=".1"><output id="forceScaleValue">1×</output></label><p class="force-hint">${lang('Seleziona una voce per evidenziarla nella scena; selezionala di nuovo per chiudere il dettaglio.','Select an item to highlight it in the scene; select it again to clear the detail.')}</p><div id="forceValues" class="force-values"></div><p class="force-explanation">${lang('Lunghezze delle frecce logaritmiche; centri di carena, deriva e gravità stimati. Componenti e risultanti sono viste alternative.','Logarithmic arrow lengths; hull, lateral resistance and gravity centres are estimated. Components and resultants are alternative views.')}</p></details>`;root.querySelectorAll('[data-force-group]').forEach(input=>input.addEventListener('change',e=>{getState().forceGroups[e.target.dataset.forceGroup]=e.target.checked;getState().forceFocus=null;update(true);}));root.querySelector('#forceScale').addEventListener('input',e=>{getState().forceScale=Number(e.target.value);update(true);});}
 function update(force=false){if(language!==getLanguage())render();const s=getState(),m=getMetrics();root.classList.toggle('hidden',!s.forces);button.setAttribute('aria-pressed',String(!!s.forces));button.classList.toggle('selected',!!s.forces);if(!s.forces)return;const config=JSON.stringify([s.forceGroups,s.forceFocus,s.forceScale]);if(!force&&lastMetric===m&&lastConfig===config)return;lastMetric=m;lastConfig=config;root.querySelectorAll('[data-force-group]').forEach(e=>e.checked=s.forceGroups[e.dataset.forceGroup]!==false);root.querySelector('#forceScale').value=s.forceScale;root.querySelector('#forceScaleValue').textContent=s.forceScale.toFixed(1)+'×';const diagram=buildForceDiagram(s,m),items=diagram.items.filter(x=>!x.quiet&&s.forceGroups[x.group]!==false);if(s.forceFocus&&!items.some(x=>x.id===s.forceFocus))s.forceFocus=null;root.querySelector('#forceValues').innerHTML=items.map(item=>`<button type="button" data-force-focus="${item.id}" aria-pressed="${s.forceFocus===item.id}" style="--force-color:${item.color}"><span><i></i>${getLanguage()==='en'?item.en:item.label}${item.estimated?` <small>${lang('stima','estimate')}</small>`:''}</span><b>${item.kind==='centre'?item.origin.map(v=>v.toLocaleString(getLanguage()==='en'?'en-GB':'it-IT',{maximumFractionDigits:1})).join(' / ')+' m':item.magnitude.toLocaleString(getLanguage()==='en'?'en-GB':'it-IT',{maximumFractionDigits:0})+' '+item.unit}</b></button>`).join('');root.querySelectorAll('[data-force-focus]').forEach(b=>b.addEventListener('click',()=>{s.forceFocus=s.forceFocus===b.dataset.forceFocus?null:b.dataset.forceFocus;update(true);}));}
 button.addEventListener('click',()=>{const s=getState();s.forces=!s.forces;s.forceFocus=null;update(true);});render();update(true);return{update};}
